{"command":"$p='./'
$t=[System.IO.File]::ReadAllText($p,[System.Text.Encoding]::UTF8)
foreach($cp in @('☝','✖','↗','🗡','❄','↑','↓','💧')){ }
foreach($pair in @(@('261D','☝☝'),@('2716','✖✖'),@('2197','↗↗'),@('1F5E1','🗡🗡'),@('2744','❄❄'))){
  $ch=[char]::ConvertFromUtf32([Convert]::ToInt32($pair[0],16))
  $i=$t.IndexOf($ch); $n=0; $vs=0
  $k=0; while($k -ge 0){ $k=$t.IndexOf($ch,$k); if($k -lt 0){break}; $n++; $nx=$k+$ch.Length; if($nx -lt $t.Length -and [int][char]$t[$nx] -eq 0xFE0F){$vs++}; $k=$nx }
  "U+$($pair[0]) count=$n withVS16=$vs"
}
"FE0F_total=$(([regex]::Matches($t,[string][char]0xFE0F)).Count)"
"ZWJ_200D=$(([regex]::Matches($t,[string][char]0x200D)).Count)"
"U+3000=$(([regex]::Matches($t,[string][char]0x3000)).Count)"","description":"统计emoji变体选择符与特殊空白字符数量"}

